-- Auto-generated from the original Prisma seed data. Safe to re-run:
-- products/inventory are upserted by unique sku, inventory balances are
-- only set on first insert so re-seeding never clobbers live scan data.

on conflict (sku) do update set ideal_stock_level = excluded.ideal_stock_level;

on conflict (sku) do nothing;

-- Seed initial stock balances for the 10 stocked products only.
-- ON CONFLICT DO NOTHING is intentional: re-running this seed must never
-- overwrite live scanned inventory balances, it only creates the row once.
select p.id, v.full_quantity, 0
from (values
  ('redken-shades-eq-09v', 9),
  ('l-or-al-professionnel-majirel-6-3', 4),
  ('wella-professionals-koleston-perfect-7-43', 10),
  ('schwarzkopf-igora-royal-5-65', 2),
  ('goldwell-topchic-6n', 5),
  ('redken-shades-eq-7na', 1),
  ('wella-professionals-illumina-color-8-69', 7),
  ('l-or-al-professionnel-inoa-7-1', 2),
  ('schwarzkopf-igora-royal-4-99', 3),
  ('goldwell-elumen-bl-all', 6)
) as v(sku, full_quantity)
join products p on p.sku = v.sku
on conflict (product_id) do nothing;

-- Seeded 10 stocked products and 289 catalog reference products.
